INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "朱世珍", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱世珍是朱元璋的父亲。他把家迁到濠州钟离。", "biography": null, "status": "draft", "id": "f2517fbe-fc97-56b3-bd90-0c7a1b27d74f"}, {"name": "陈氏（朱元璋母）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "陈氏是朱元璋的母亲。", "biography": null, "status": "draft", "id": "3ba6e580-092e-5b69-8c09-c5dbef1dfd98"}, {"name": "刘继祖（朱元璋同乡）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "刘继祖是朱元璋的同乡。朱家没有地方安葬亡故的亲人时，他把土地给了朱家。", "biography": null, "status": "draft", "id": "2e65780b-449d-5b1f-a3d2-049df703491e"}, {"status": "draft", "name": "郭子兴", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，1352年聚壮士称元帅据濠州，留用朱元璋，后将马公托孤养女嫁之。", "biography": null, "id": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd"}, {"status": "draft", "name": "孙德崖", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1352年与郭子兴等聚众攻城的首领。", "biography": null, "id": "b85cbc5f-c7d2-52e3-8ecc-4edd681847c1"}, {"status": "draft", "name": "马氏（郭子兴养女）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "宿州马公最小的女儿，父死后为郭子兴养女，1352年嫁朱元璋；原称季女，不补年龄或俗传名字。", "biography": null, "id": "4b0e7356-b115-5755-bcaf-fc1dd998b656"}, {"name": "马公（郭子兴故交）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "宿州人，郭子兴刎颈交，亡后其最小的女儿由郭子兴抚养，本书未具名，不由婚年反推卒年。", "biography": null, "status": "draft", "id": "ddf0cb54-c719-564c-ad4d-65408a6ec4ec"}, {"status": "draft", "name": "老彭", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1351年受赵君用邀与芝麻李等起兵、取徐州的勇悍者，只沿绰称不补名。", "biography": null, "id": "2f4dddf1-de05-5220-8b77-96f5107d88b5"}, {"status": "draft", "name": "赵君用", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "李二所处乡社社长，1351年邀老彭共与李二等起兵，夺取徐州。", "biography": null, "id": "352c2555-5c49-5bd2-985f-bfc346efd6da"}, {"status": "draft", "name": "李二", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "萧县人，号芝麻李，曾尽芝麻仓济饥，1351年与赵君用老彭等取徐州。", "biography": null, "id": "cbabd469-3dfe-5bd5-832d-9e74aa856f26"}, {"status": "draft", "name": "贾鲁", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "元工部郎中，1348年主持郓城行都水监，后进便漕及治河策。", "biography": null, "id": "cfed2ba9-8008-5f3d-bd9b-12b92d00dbdc"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "费聚", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1353年随朱元璋招定远民兵、留下候讯。", "biography": null, "status": "draft", "id": "36ba4a1f-2076-5446-9a83-4d7c8bf799f6"}, {"name": "李善长", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "1353年受朱元璋留为幕书记。", "biography": null, "status": "draft", "id": "fcb986aa-d440-5732-984a-f4c744f5a06d"}, {"name": "张士诚", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "白驹场盐民，率众起兵，陷高邮称诚王建周。", "biography": null, "status": "draft", "id": "7fbe0af4-cc39-5fb7-9fa8-c94e110ad986"}, {"status": "draft", "name": "托克托（满济勒噶台子）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "满济勒噶台之子，1338年由中丞任御史大夫。", "biography": null, "id": "6ac59c55-e3f1-5a47-bb1d-406fa510ba1d"}, {"name": "耿再成", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1354—55年从朱元璋守战六合和阳。", "biography": null, "status": "draft", "id": "e2654eb1-d625-5630-ab59-98ae745307ea"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "濠州一带发生饥荒和疫病", "description": "《明史》记至正四年当地遭遇旱灾和蝗灾，接着发生严重的饥荒和疫病。 按原历纪年，事情发生在公元1344至1345年之间。", "start_year": null, "end_year": null, "time_original": "至正四年", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "995ac677-5f50-56e5-b386-efd4c3fb1a0a"}, {"title": "刘继祖给朱元璋土地安葬亲人", "description": "父母和一位兄长相继去世后，朱元璋家贫，无法安葬亲人。同乡刘继祖给了他一块地，他才得以安葬。史书说这处墓地就是后来的凤阳陵。 按原历纪年，事情发生在公元1344至1345年之间。", "start_year": null, "end_year": null, "time_original": "至正四年所叙家难", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "86ed304c-9fe3-5ac3-b9eb-6c245ec6a994"}, {"title": "朱元璋到皇觉寺为僧", "description": "亲人去世后，朱元璋失去依靠，便到皇觉寺做了僧人。 按原历纪年，事情发生在公元1344至1345年之间。", "start_year": null, "end_year": null, "time_original": "至正四年家难之后", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7afa5cb6-fa2e-577c-9855-71b76f21cea5"}, {"title": "朱元璋外出谋生后返回皇觉寺", "description": "入寺一个多月后，朱元璋外出到合肥一带谋生。《明史》说他在途中生病，由两名穿紫衣的人照料，病好后便找不到他们。他先后走过光、固、汝、颍等州，历时三年才回到寺里。", "start_year": null, "end_year": null, "time_original": "入皇觉寺逾月后外出，历时三年", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fc783e00-5cab-5224-bd3b-5e10935c528f"}, {"title": "郭子兴聚众称元帅攻城", "description": "定远郭子兴散家财结壮士，集少年数千，称节制元帅，与孙德崖及俞鲁潘等人攻城。", "start_year": 1352, "end_year": 1352, "time_original": "《续资治通鉴》卷210；本事原载纪年折合公元1352年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ed770a46-f36f-5d4c-b33d-c993517abad5"}, {"title": "朱元璋投郭子兴濠州军", "description": "皇觉寺毁于战乱后，钟离朱元璋赴濠州投郭子兴，入城时一度被疑为间谍，郭询问缘由后留在左右。其后领九夫、参议和奉命攻讨属后续相对官序，另保未明年月。", "start_year": 1352, "end_year": 1352, "time_original": "《续资治通鉴》卷210；本事原载纪年折合公元1352年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1e5b3d0-292a-5689-88d0-7bd4738442b7"}, {"title": "郭子兴以养女马氏妻朱元璋", "description": "郭子兴与妾张氏商议招揽豪杰，决定将养女马氏嫁给朱元璋，遂成婚。马氏为故交马公最小的女儿，托付和收养属于此前附叙，另分未知年月，不由婚年推父卒年或女儿年龄。", "start_year": 1352, "end_year": 1352, "time_original": "《续资治通鉴》卷210；本事原载纪年折合公元1352年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0dc55137-dc78-5a10-9bc4-16a2f1fbbbb0"}, {"title": "托克托破徐州屠城芝麻李逃", "description": "托克托攻徐州西门，按伊苏计用巨石炮昼夜攻，城破芝麻李逃，元军获旗鼓伞、焚积聚擒千户，遂屠城。", "start_year": 1352, "end_year": 1352, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1352年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "42cd3699-cbcd-53fe-adb4-e1cf4cc3c291"}, {"title": "贾鲁追彭大赵君用", "description": "徐州失后彭大赵君用率余军赴濠，托克托命贾鲁追击。", "start_year": 1352, "end_year": 1352, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1352年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "38b4d28b-3ee9-5f30-96b3-c414f28cd8bb"}, {"title": "朱元璋彭大救郭子兴", "description": "孙德崖纳彭赵后受制，赵君用怨郭厚彭薄己，与孙拘郭欲杀。朱元璋携郭子求彭大援，合兵破械救郭。", "start_year": 1352, "end_year": 1352, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1352年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7758cec3-386c-54ba-ab88-26f43d8b252a"}, {"title": "贾鲁围濠州", "description": "贾鲁率兵围濠州。", "start_year": 1352, "end_year": 1352, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1352年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07f316e6-8818-56e3-9a07-2ad6d3d82247"}, {"title": "贾鲁围濠军中卒", "description": "贾鲁与伊撤察喇攻濠，誓当日取城后食，临城头眩病急仍令军不散，后拒药卒，官军解围。", "start_year": 1353, "end_year": 1353, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1353年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "da7ea1f9-1cf2-5820-873e-a3187432d232"}, {"title": "朱元璋募700归濠授镇抚", "description": "濠州解围后，朱元璋返乡募七百余人，六月回濠，郭子兴授镇抚。", "start_year": 1353, "end_year": 1353, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1353年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00618338-e919-57e4-a4fa-df0b567f864e"}, {"title": "朱元璋南略招降定远民兵", "description": "朱元璋因彭赵暴横，交出七百军，与徐达等二十四人南略，病返后仍赴定远张家堡劝降，遣费聚留候。得知其拟另投，率三百诱拘其帅，招三千壮士，又降秦把头八百余。", "start_year": 1353, "end_year": 1353, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1353年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "791c339b-b431-599b-b687-3100b26168de"}, {"title": "花云夜破缪大亨降2万", "description": "朱元璋命花云夜袭横涧山，缪大亨率二万众降。", "start_year": 1353, "end_year": 1353, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1353年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6511c7ed-436b-5582-b913-2bfeace3481c"}, {"title": "朱元璋留李善长掌书记", "description": "朱元璋略滁阳遇李善长，留任幕书记，令其协诸将、不效毁将致败之幕客。", "start_year": 1353, "end_year": 1353, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1353年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d124f8e2-346a-59f2-b7c6-a66102fb7949"}, {"title": "高邮陷纳苏喇鼎父子死张建周", "description": "纳苏喇鼎守高邮，阿苏卫等友军退走，他命三子离开，两子不肯，与他一同战死。张士诚以高邮为都、称诚王、国号大周、改元天祐。本书在至正十三年叙此，明史张士诚传同明确十三年；不据常见后说直接改本书年条，也不说三子全死。", "start_year": 1353, "end_year": 1353, "time_original": "《续资治通鉴》卷211；本事原载纪年折合公元1353年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e0cf5d04-27ac-53cd-9839-b4c39d7e6079"}, {"title": "托克托高邮败张西平六合", "description": "托克托至高邮，在城外大败张士诚，分军西取六合。", "start_year": 1354, "end_year": 1354, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1354年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aeeb750e-f748-5ba0-b623-cfdc6ae96a9d"}, {"title": "朱援六合诈战解滁危", "description": "郭子兴因私怨不愿救六合，朱元璋以两城相依说服他，领兵与耿再成守瓦梁垒，设伏击退官军，又以牛酒还马、自称良民自保的策略使对方撤军，滁州得以保全。自辩是战术说辞，不等同没有军事目的。", "start_year": 1354, "end_year": 1354, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1354年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c6c6db8e-6a6d-5bb7-a723-c1ecf12d2cf1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "儿子", "description": "朱元璋是朱世珍四个儿子中最小的一个。", "status": "draft", "id": "0f6dbb49-c2c9-5980-bfd1-1a5a68454710", "person_a": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "person_b": "f2517fbe-fc97-56b3-bd90-0c7a1b27d74f"}, {"relation_type": "儿子", "description": "陈氏是朱元璋的母亲。", "status": "draft", "id": "9f16ba07-a6f1-5111-8561-8f9c7826630d", "person_a": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "person_b": "3ba6e580-092e-5b69-8c09-c5dbef1dfd98"}, {"relation_type": "部属", "description": "来从后留左右受命将兵，限早年所述。", "status": "draft", "id": "c69255b8-8c89-527b-9d7b-0d5f2bcb1737", "person_a": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "person_b": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd"}, {"relation_type": "养女", "description": "原抚为己女。", "status": "draft", "id": "ccc39fb6-da61-54aa-b1fa-ed865eff07de", "person_a": "4b0e7356-b115-5755-bcaf-fc1dd998b656", "person_b": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd"}, {"relation_type": "女儿", "description": "马公季女。", "status": "draft", "id": "e30850fa-33e3-5e9f-a069-a3de81e9bd17", "person_a": "4b0e7356-b115-5755-bcaf-fc1dd998b656", "person_b": "ddf0cb54-c719-564c-ad4d-65408a6ec4ec"}, {"relation_type": "妻子", "description": "原以女妻元璋。", "status": "draft", "id": "0e992389-971d-593e-b9a8-dcbb27857c7e", "person_a": "4b0e7356-b115-5755-bcaf-fc1dd998b656", "person_b": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

