SELECT id, person_id, event_id, role, status FROM jsonb_populate_recordset(NULL::public.person_event, '[{"role": "获赠墓地并安葬亲人", "status": "draft", "id": "519097b5-82c4-59c4-9786-cf344b1e239a", "person_id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "event_id": "86ed304c-9fe3-5ac3-b9eb-6c245ec6a994"}, {"role": "给朱元璋墓地", "status": "draft", "id": "903fcd75-5f52-534e-8ec9-cb7572f0a288", "person_id": "2e65780b-449d-5b1f-a3d2-049df703491e", "event_id": "86ed304c-9fe3-5ac3-b9eb-6c245ec6a994"}, {"role": "入寺为僧", "status": "draft", "id": "c169666b-24f6-53a9-8480-2beee388d661", "person_id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "event_id": "7afa5cb6-fa2e-577c-9855-71b76f21cea5"}, {"role": "在外谋生后回寺", "status": "draft", "id": "0a46759d-67d4-558c-b96b-d18044d8aa07", "person_id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "event_id": "fc783e00-5cab-5224-bd3b-5e10935c528f"}, {"role": "聚众称元帅", "status": "draft", "id": "2de8e74f-2f15-5ea7-946d-7cc7c8c73e15", "person_id": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd", "event_id": "ed770a46-f36f-5d4c-b33d-c993517abad5"}, {"role": "合众攻城", "status": "draft", "id": "a246f848-d1b8-5e6b-95df-8ea3f8cdfc7a", "person_id": "b85cbc5f-c7d2-52e3-8ecc-4edd681847c1", "event_id": "ed770a46-f36f-5d4c-b33d-c993517abad5"}, {"role": "投军被留在左右", "status": "draft", "id": "1fcdd528-c5c7-5f99-815e-4b0306379353", "person_id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "event_id": "d1e5b3d0-292a-5689-88d0-7bd4738442b7"}, {"role": "留用朱元璋", "status": "draft", "id": "47ab06a4-2141-5629-b1cb-9e855cd79311", "person_id": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd", "event_id": "d1e5b3d0-292a-5689-88d0-7bd4738442b7"}, {"role": "以养女嫁将", "status": "draft", "id": "bddf7512-0c05-57f3-a82e-f02d073a4dc7", "person_id": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd", "event_id": "0dc55137-dc78-5a10-9bc4-16a2f1fbbbb0"}, {"role": "嫁朱元璋", "status": "draft", "id": "f905d8ef-ede3-51ff-8c8e-f6db005730d0", "person_id": "4b0e7356-b115-5755-bcaf-fc1dd998b656", "event_id": "0dc55137-dc78-5a10-9bc4-16a2f1fbbbb0"}, 