INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "明太祖朱元璋，字国瑞。他的父亲朱世珍把家迁到濠州钟离。朱元璋是家中最小的儿子。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000345；元末，原文未载这项身份的具体年月", "note": "原文：諱元璋，字國瑞，姓朱氏。先世家沛，徙句容，再徙泗州。父世珍，始徙濠州之鍾離。生四子，太祖其季也。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "e1b1ec61-3ac5-577e-b86c-cd265ccff496", "subject_id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "source_id": "4f0daaa2-2bcf-5a68-9150-a094a614a714"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱世珍是朱元璋的父亲。他把家迁到濠州钟离。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000345；元末，原文未载这项身份的具体年月", "note": "原文：父世珍，始徙濠州之鍾離。生四子，太祖其季也。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "e2d051ba-f945-5cb4-a4a2-e0b35f7ecf30", "subject_id": "f2517fbe-fc97-56b3-bd90-0c7a1b27d74f", "source_id": "4f0daaa2-2bcf-5a68-9150-a094a614a714"}, {"subject_table": "person", "field_path": "description", "claim_text": "陈氏是朱元璋的母亲。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000345；元末，原文未载这项身份的具体年月", "note": "原文：母陳氏。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "67d12bb7-7369-598e-a5ca-deebd9f1ed8e", "subject_id": "3ba6e580-092e-5b69-8c09-c5dbef1dfd98", "source_id": "4f0daaa2-2bcf-5a68-9150-a094a614a714"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘继祖是朱元璋的同乡。朱家没有地方安葬亡故的亲人时，他把土地给了朱家。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000347；元末，原文未载这项身份的具体年月", "note": "原文：太祖時年十七，父母兄相繼歿，貧不克葬。里人劉繼祖與之地，乃克葬，即鳳陽陵也。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "4226ab90-3789-5610-a856-f7ee3bbcd0ce", "subject_id": "2e65780b-449d-5b1f-a3d2-049df703491e", "source_id": "4bd1111f-c798-53fa-8fc1-7d1e98a3f73b"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭子兴是定远人，至正十二年与孙德崖等人在濠州起兵。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000349；元末，原文未载这项身份的具体年月", "note": "原文：十二年春二月，定遠人郭子興與其黨孫德崖等起兵濠州。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "4181127a-fab5-5bfc-af70-312e5cf3b47e", "subject_id": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd", "source_id": "e1af1c62-96cc-5882-9798-966a33568cd2"}, {"subject_table": "person", "field_path": "description", "claim_text": "孙德崖与郭子兴等人在濠州起兵。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000349；元末，原文未载这项身份的具体年月", "note": "原文：定遠人郭子興與其黨孫德崖等起兵濠州。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "8ff6c2e3-47fd-5e68-923b-9949b3cfccb1", "subject_id": "b85cbc5f-c7d2-52e3-8ecc-4edd681847c1", "source_id": "e1af1c62-96cc-5882-9798-966a33568cd2"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭子兴抚养马公的女儿，并把她嫁给朱元璋。她后来成为高皇后。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000349；元末，原文未载这项身份的具体年月", "note": "原文：遂妻以所撫馬公女，即高皇后也。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "3966293a-7b6a-56d4-8161-7deb16b140a3", "subject_id": "4b0e7356-b115-5755-bcaf-fc1dd998b656", "source_id": "e1af1c62-96cc-5882-9798-966a33568cd2"}, {"subject_table": "person", "field_path": "description", "claim_text": "马公的女儿由郭子兴抚养，后来嫁给朱元璋。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000349；元末，原文未载这项身份的具体年月", "note": "原文：所撫馬公女，即高皇后也。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "eec964cb-4fee-5eb8-a469-965cbfb0907e", "subject_id": "ddf0cb54-c719-564c-ad4d-65408a6ec4ec", "source_id": "e1af1c62-96cc-5882-9798-966a33568cd2"}, {"subject_table": "person", "field_path": "description", "claim_text": "徐州被元军攻克后，彭大与赵均用逃往濠州。《续资治通鉴》在同一事件中也称他为彭大。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000350；元末，原文未载这项身份的具体年月", "note": "原文：彭大、趙均用奔濠，德崖等納之。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "38df6067-2da9-54ea-b5c9-794caf03e86c", "subject_id": "2f4dddf1-de05-5220-8b77-96f5107d88b5", "source_id": "0497732d-5657-5ba2-af6e-70e6f6becac5